import { useEffect, useState, type FormEvent } from "react";
import { bytes, connectionOptions, transportRequest, relayTestConfiguration, endpoint, request, saveSettings, settingsPatch, managedSettings, type Credentials, type PanelProps, type RelayStatus } from "./api";

const css = `
.turn-panel{height:100%;overflow:hidden;background:var(--bg);color:var(--text);font:13px/1.5 var(--font-base);--turn-card:var(--bg-card);--turn-muted:var(--text-muted);--turn-border:var(--border)}
.turn-panel *{box-sizing:border-box}.turn-panel a{color:var(--accent)}.turn-shell{height:100%;display:flex;flex-direction:column;min-height:0}.turn-body{flex:1;min-height:0;overflow:auto;padding:16px}.turn-header{padding:12px 16px;flex-shrink:0}.turn-header,.turn-row{display:flex;align-items:center;justify-content:space-between;gap:16px}.turn-header h1{margin:0;font-size:16px;font-weight:600}.turn-panel p{margin:6px 0;color:var(--turn-muted)}.turn-badge{border:1px solid var(--turn-border);padding:4px 10px;border-radius:var(--radius-sm);font-size:12px;white-space:nowrap}.turn-badge.good{background:color-mix(in srgb,var(--success) 10%,transparent);color:var(--success);border-color:color-mix(in srgb,var(--success) 30%,transparent)}.turn-badge.warn{background:color-mix(in srgb,var(--warn) 10%,transparent);color:var(--warn);border-color:color-mix(in srgb,var(--warn) 30%,transparent)}.turn-nav{display:flex;flex-shrink:0;gap:4px;border-bottom:1px solid var(--turn-border);padding:0 12px;margin:0}.turn-nav button{background:none;border:0;border-bottom:2px solid transparent;color:var(--turn-muted);padding:6px 12px;border-radius:var(--radius-sm) var(--radius-sm) 0 0;font-size:12px}.turn-nav button[aria-selected=true]{color:var(--accent);border-color:var(--accent);font-weight:600}.turn-panel button{font:inherit;cursor:pointer}.turn-panel button:disabled{cursor:default;opacity:.5}.turn-button{border:1px solid var(--turn-border);border-radius:var(--radius-md);padding:8px 12px;background:var(--turn-card);color:inherit;font-size:12px!important}.turn-button.primary{background:var(--accent);color:var(--bg);border-color:transparent}.turn-panel button:focus-visible,.turn-panel input:focus-visible,.turn-panel select:focus-visible,.turn-panel textarea:focus-visible{outline:2px solid var(--accent);outline-offset:3px}.turn-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:22px}.turn-card{background:var(--turn-card);border:1px solid var(--turn-border);border-radius:var(--radius-lg);padding:16px;min-width:0}.turn-card h2{font-size:14px;font-weight:600;margin:0 0 16px}.turn-value{font-size:24px;line-height:1.2;letter-spacing:-1px;font-variant-numeric:tabular-nums;margin:10px 0 5px}.turn-small{font-size:12px;color:var(--turn-muted)}.turn-grid{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:18px}.turn-panel code,.turn-panel pre{font:12px/1.6 var(--font-mono-fixed);overflow-wrap:anywhere;white-space:pre-wrap}.turn-endpoint{padding:13px 0;border-top:1px solid var(--turn-border)}.turn-endpoint:first-of-type{border-top:0}.turn-endpoint code{display:block;margin-top:4px}.turn-label{display:block;font-size:12px;color:var(--turn-muted);margin-bottom:6px}.turn-details{display:grid;grid-template-columns:110px minmax(0,1fr);gap:12px;font-size:12px;margin:0}.turn-details dt{color:var(--turn-muted)}.turn-details dd{margin:0;overflow-wrap:anywhere}.turn-banner{border:1px solid var(--turn-border);border-radius:var(--radius-md);padding:12px 15px;margin-bottom:20px;font-size:12px}.turn-banner.error{border-color:color-mix(in srgb,var(--error) 30%,transparent);color:var(--error)}.turn-fields{display:grid;grid-template-columns:1fr 1fr;gap:18px}.turn-fields label{display:block}.turn-panel input:not([type=checkbox]),.turn-panel select,.turn-panel textarea{width:100%;border:1px solid var(--turn-border);border-radius:var(--radius-sm);background:var(--bg-input);color:inherit;font:inherit;padding:9px 10px}.turn-panel textarea{font:12px/1.5 var(--font-mono-fixed);resize:vertical}.turn-panel input[type=file]{font-size:11px;padding:5px;border:0}.turn-secret{-webkit-text-security:disc}.turn-section{margin-bottom:20px}.turn-wide{grid-column:1/-1}.turn-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:20px}.turn-table{border-collapse:collapse;width:100%;font-size:12px}.turn-table th,.turn-table td{text-align:left;padding:11px 0;border-bottom:1px solid var(--turn-border)}.turn-table th{color:var(--turn-muted);font-weight:500}.turn-foot{margin-top:24px;font-size:11px;color:var(--turn-muted)}.turn-empty{padding:48px 20px;text-align:center}.turn-credentials{margin-top:20px}.turn-check{display:flex!important;align-items:center;gap:8px;font-size:12px;color:var(--turn-muted)}
@media(max-width:760px){.turn-body{padding:12px}.turn-stats{grid-template-columns:repeat(2,minmax(0,1fr))}.turn-grid,.turn-fields{grid-template-columns:1fr}.turn-header{align-items:flex-start}.turn-details{grid-template-columns:95px minmax(0,1fr)}}
`;

const basicFields = [["public_ip", "Public IPv4"], ["public_host", "TURN hostname"], ["realm", "Authentication realm"], ["bind_ip", "Bind IPv4"]] as const;
const capacityFields = [["credential_ttl_seconds", "Maximum credential lifetime (seconds)", 60, 86400], ["max_allocations", "Maximum allocations", 1, 64], ["allocations_per_credential", "Allocations per credential", 1, 16], ["bytes_per_second", "Bytes per second per allocation", 65536, 104857600]] as const;

function Settings({ props, status, notify }: { props: PanelProps; status: RelayStatus; notify: (text: string) => void }) {
  const [draft, setDraft] = useState({ ...status.configuration });
  const [domains, setDomains] = useState<string[]>([]);
  useEffect(() => { if (draft.tls_mode !== "managed") return; const controller = new AbortController(); void request<{domains:{name:string}[]}>(endpoint(props.installId, props.projectId || draft.dns_project_id || "", "/tls/domains"), undefined, controller.signal).then(result => setDomains((result.domains || []).map(domain => domain.name))).catch(() => setDomains([])); return () => controller.abort(); }, [draft.tls_mode, draft.dns_project_id, props.installId, props.projectId]);
  const [certificate, setCertificate] = useState(""); const [privateKey, setPrivateKey] = useState(""); const [secret, setSecret] = useState("");
  const [reveal, setReveal] = useState(false); const [busy, setBusy] = useState(false); const [error, setError] = useState("");
  const change = (name: string, value: string) => setDraft(old => ({ ...old, [name]: value }));
  const upload = async (file: File | undefined, setter: (text: string) => void) => { if (!file) return; if (file.size > 65536) { setError("Certificate files must be at most 64 KiB."); return; } try { setter(await file.text()); setError(""); } catch { setError("Could not read the selected file."); } };
  const save = async (event: FormEvent) => {
    event.preventDefault(); setError(""); setBusy(true);
    try {
      const patch = managedSettings(settingsPatch(status.configuration, draft, draft.tls_mode === "managed" ? "" : certificate, draft.tls_mode === "managed" ? "" : privateKey, secret), draft, status.managed_tls.storage_key_configured, props.projectId);
      if (!Object.keys(patch).length) { notify("No settings have changed."); return; }
      const restarted = await saveSettings(props, patch);
      setCertificate(""); setPrivateKey(""); setSecret(""); setReveal(false);
      notify(restarted ? "Settings saved. TURN is restarting with the new configuration." : "Settings saved. Restart TURN from its deployment controls to apply them.");
    } catch (error) { setError(error instanceof Error ? error.message : "Could not save settings."); } finally { setBusy(false); }
  };
  return <form onSubmit={save}>
    {error && <div role="alert" className="turn-banner error">{error}</div>}
    <section className="turn-card turn-section"><h2>Relay endpoint</h2><div className="turn-fields">{basicFields.map(([name, label]) => <label key={name}><span className="turn-label">{label}</span><input required value={draft[name] || ""} onChange={event => change(name, event.target.value)} autoComplete="off" /></label>)}</div><p className="turn-small">Use the public address of the instance running TURN. Its hostname must point directly to that instance.</p></section>
    <section className="turn-card turn-section"><h2>Listener ports</h2><div className="turn-fields">
      {[["udp_port","UDP client port"],["tcp_port","TCP client port"]].map(([name,label]) => <label key={name}><span className="turn-label">{label}</span><input type="number" required min={1} max={65535} step={1} value={draft[name] || "3478"} onChange={event => change(name,event.target.value)} /></label>)}
      <label className="turn-wide"><span className="turn-label">TLS client ports (comma-separated)</span><input required value={draft.tls_ports || "5349"} onChange={event => change("tls_ports",event.target.value)} placeholder="5349,443,8443" /></label>
    </div><p className="turn-small">Use several TLS ports to compare connections without restarting between tests. Port 443 must be free on the relay host; HTTPS services may already use it. Open every selected port in the host and cloud firewalls.</p></section>
    <section className="turn-card turn-section"><div className="turn-row"><h2>TLS certificate</h2><span className={`turn-badge ${status.tls ? "good" : "warn"}`}>{status.tls ? "Configured" : "Setup required"}</span></div>
      <label><span className="turn-label">Certificate management</span><select value={draft.tls_mode || "manual"} onChange={event => change("tls_mode", event.target.value)}><option value="managed">Automatic through Domains and Let's Encrypt</option><option value="manual">Import a certificate</option></select></label>
      {draft.tls_mode === "managed" ? <>
        <p className="turn-small">Bind Domains in this app's dependencies. TURN creates its subdomain A record, validates ownership through DNS and renews certificates automatically. Existing conflicting records are preserved.</p>
        <div className="turn-fields" style={{marginTop:18}}>
          <label><span className="turn-label">DNS zone</span><input required list={`turn-zones-${props.installId}`} value={draft.dns_zone || ""} onChange={event => change("dns_zone", event.target.value)} placeholder="example.com" /><datalist id={`turn-zones-${props.installId}`}>{domains.map(domain => <option key={domain} value={domain} />)}</datalist></label>
          {!props.projectId && <label><span className="turn-label">Project owning the DNS zone</span><input required value={draft.dns_project_id || ""} onChange={event => change("dns_project_id", event.target.value)} /></label>}
          <label><span className="turn-label">Certificate contact email (optional)</span><input type="email" value={draft.acme_email || ""} onChange={event => change("acme_email", event.target.value)} /></label>
        </div>
        <label className="turn-check"><input type="checkbox" required checked={draft.acme_accept_terms === "true"} onChange={event => change("acme_accept_terms", String(event.target.checked))} />I accept the <a href="https://letsencrypt.org/repository/" target="_blank" rel="noreferrer">Let's Encrypt subscriber agreement</a>.</label>
        <p className="turn-small">Private keys stay encrypted in this installation. Renewals load without interrupting relay sessions. The relay hostname must point directly to its public IPv4.</p>
      </> : <>
      <p className="turn-small">Supply a certificate chain covering {draft.public_host || "your TURN hostname"} and its matching private key. Existing material is kept when both fields are left blank.</p>
      <div className="turn-fields" style={{ marginTop: 18 }}>
        <label><span className="turn-label">Certificate chain (PEM)</span><textarea rows={6} value={certificate} onChange={event => setCertificate(event.target.value)} spellCheck={false} autoComplete="off" placeholder="Paste a new certificate chain…" /><input type="file" accept=".pem,.crt,.cer,.txt" aria-label="Upload certificate chain" onChange={event => void upload(event.target.files?.[0], setCertificate)} /></label>
        <label><span className="turn-label">Private key (PEM)</span><textarea rows={6} value={privateKey} onChange={event => setPrivateKey(event.target.value)} className={reveal ? "" : "turn-secret"} spellCheck={false} autoComplete="off" placeholder="Paste the matching private key…" /><input type="file" accept=".pem,.key,.txt" aria-label="Upload private key" onChange={event => void upload(event.target.files?.[0], setPrivateKey)} /></label>
      </div><label className="turn-check"><input type="checkbox" checked={reveal} onChange={event => setReveal(event.target.checked)} />Show entered private key</label><p className="turn-small">Keys are saved in encrypted installation settings. TURN never returns the stored private key.</p></>}
    </section>
    <section className="turn-card turn-section"><h2>Capacity and access</h2><div className="turn-fields">{capacityFields.map(([name, label, min, max]) => <label key={name}><span className="turn-label">{label}</span><input type="number" required min={min} max={max} step={1} value={draft[name] || ""} onChange={event => change(name, event.target.value)} /></label>)}
      <label className="turn-wide"><span className="turn-label">Allowed peer networks (optional IPv4 CIDRs, comma-separated)</span><input value={draft.allowed_peer_cidrs || ""} onChange={event => change("allowed_peer_cidrs", event.target.value)} placeholder="Public media peers only" /></label>
      <label className="turn-wide"><span className="turn-label">Replace credential signing secret (leave blank to keep current secret)</span><input type="password" autoComplete="new-password" minLength={32} maxLength={1024} value={secret} onChange={event => setSecret(event.target.value)} placeholder="At least 32 random characters" /></label>
    </div></section>
    <p className="turn-small">Saving changes restarts TURN. {status.active_allocations ? `${status.active_allocations} active allocation(s) may be interrupted; drain the deployment first.` : "There are no active allocations."}</p>
    <div className="turn-actions"><button className="turn-button primary" disabled={busy}>{busy ? "Validating and saving…" : "Save and restart"}</button></div>
  </form>;
}

function CredentialForm({ props, status, copy }: { props: PanelProps; status: RelayStatus; copy: (value: string) => Promise<void> }) {
  const [project, setProject] = useState(props.projectId); const [session, setSession] = useState(""); const [ttl, setTTL] = useState(String(Math.min(3600, Number(status.configuration.credential_ttl_seconds))));
  const [result, setResult] = useState<Credentials | null>(null); const [busy, setBusy] = useState(false); const [error, setError] = useState("");
  const [reveal, setReveal] = useState(false);
  const [selection,setSelection] = useState("all");
  useEffect(() => { if (!result) return; const timer = setTimeout(() => setResult(null), Math.max(0, result.expires_at * 1000 - Date.now())); return () => clearTimeout(timer); }, [result]);
  const generate = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setError(""); setResult(null); setReveal(false); try { setResult(await request<Credentials>(endpoint(props.installId, props.projectId, "/credentials"), { project_id: project, session_id: session, ttl_seconds: Number(ttl), ...transportRequest(selection) })); } catch (error) { setError(error instanceof Error ? error.message : "Could not create credentials."); } finally { setBusy(false); } };
  return <section className="turn-card"><h2>Temporary ICE credentials</h2><p className="turn-small">Create credentials for an authorized project and session. They expire automatically and are cleared when you leave this view.</p>
    <p className="turn-small">For an A/B call test, choose UDP, TCP or one TLS port, then copy the forced-relay configuration into the test softphone. Compare packet loss, jitter and round-trip time in its WebRTC statistics.</p>
    {error && <div role="alert" className="turn-banner error">{error}</div>}
    <label style={{display:"block",marginTop:16}}><span className="turn-label">Test transport</span><select value={selection} onChange={event => {setSelection(event.target.value);setResult(null);setReveal(false);}}>{connectionOptions(status).map(option => <option key={option.value} value={option.value}>{option.label}</option>)}</select></label>
    <form onSubmit={generate}><div className="turn-fields" style={{ marginTop: 20 }}><label><span className="turn-label">Project ID</span><input required maxLength={256} value={project} readOnly={!!props.projectId} onChange={event => setProject(event.target.value)} /></label><label><span className="turn-label">Session ID</span><input required maxLength={256} value={session} onChange={event => setSession(event.target.value)} placeholder="Call or peer session identifier" /></label><label><span className="turn-label">Lifetime (seconds)</span><input type="number" required min={60} max={Number(status.configuration.credential_ttl_seconds)} value={ttl} onChange={event => setTTL(event.target.value)} /></label></div>
      <div className="turn-actions"><button className="turn-button primary" disabled={busy || !status.admitting}>{busy ? "Creating…" : "Create temporary credentials"}</button>{!status.admitting && <span className="turn-small">The relay is not admitting new sessions.</span>}</div>
    </form>
    {result && <div className="turn-credentials"><div className="turn-row"><span className="turn-small">Expires {new Date(result.expires_at * 1000).toLocaleString()}</span><button type="button" className="turn-button" onClick={() => void copy(JSON.stringify(result.ice_servers, null, 2))}>Copy ICE configuration</button></div><pre>{JSON.stringify(result.ice_servers.map(server => ({ ...server, credential: reveal ? server.credential : "•••••••• (hidden)" })), null, 2)}</pre><label className="turn-check"><input type="checkbox" checked={reveal} onChange={event => setReveal(event.target.checked)} />Show credential</label><button type="button" className="turn-button" style={{ marginTop: 12 }} onClick={() => { setResult(null); setReveal(false); }}>Clear credentials</button><button type="button" className="turn-button" style={{marginLeft:10}} onClick={() => void copy(JSON.stringify(relayTestConfiguration(result),null,2))}>Copy forced-relay test configuration</button></div>}
  </section>;
}

export default function TurnPanel(props: PanelProps) {
  const [tab, setTab] = useState("overview"); const [status, setStatus] = useState<RelayStatus | null>(null); const [error, setError] = useState("");
  const [notice, setNotice] = useState(""); const [updated, setUpdated] = useState(0); const [revision, setRevision] = useState(0);
  useEffect(() => { setStatus(null); setError(""); setNotice(""); setTab("overview"); }, [props.installId, props.projectId]);
  useEffect(() => {
    let active = true; let pending = false; const controller = new AbortController();
    const load = async () => { if (pending) return; pending = true; try { const value = await request<RelayStatus>(endpoint(props.installId, props.projectId, "/status"), undefined, controller.signal); if (active) { setStatus(value); setUpdated(Date.now()); setError(""); } } catch (error) { if (active) setError(error instanceof Error ? error.message : "Could not reach TURN."); } finally { pending = false; } };
    void load(); const timer = setInterval(() => void load(), 5000); return () => { active = false; controller.abort(); clearInterval(timer); };
  }, [props.installId, props.projectId, revision]);
  useEffect(() => { if (!notice) return; const timer = setTimeout(() => setNotice(""), 8000); return () => clearTimeout(timer); }, [notice]);
  const copy = async (value: string) => { try { await navigator.clipboard.writeText(value); setNotice("Copied to clipboard."); } catch { setError("Clipboard access is unavailable. Select and copy the text manually."); } };
  const badge = status?.admitting && !error ? "Online" : status ? status.state.charAt(0).toUpperCase() + status.state.slice(1) : "Connecting";
  return <div className="turn-panel"><style>{css}</style><div className="turn-shell">
    <header className="turn-header"><div><h1>TURN relay</h1><p className="turn-small">Relay status, TLS and connection settings</p></div><div className="turn-row"><span className={`turn-badge ${status?.admitting && !error ? "good" : "warn"}`}>{error ? "Unreachable" : badge}</span><button type="button" className="turn-button" onClick={() => setRevision(value => value + 1)}>Refresh</button></div></header>
    <nav className="turn-nav" role="tablist" aria-label="TURN views">{["overview", "settings", "credentials"].map(view => <button type="button" role="tab" key={view} id={`turn-${props.installId}-${view}`} aria-controls={`turn-${props.installId}-content`} aria-selected={tab === view} onClick={() => { setTab(view); setNotice(""); }}>{view.charAt(0).toUpperCase() + view.slice(1)}</button>)}</nav>
    <main className="turn-body">
    {notice && <div role="status" className="turn-banner">{notice}</div>}{error && <div role="alert" className="turn-banner error">{error}</div>}
    {!status ? <div className="turn-empty"><p>{error ? "The relay is unavailable. Check its deployment and try refreshing." : "Loading relay status…"}</p></div> : <div role="tabpanel" id={`turn-${props.installId}-content`} aria-labelledby={`turn-${props.installId}-${tab}`} key={`${props.installId}:${props.projectId}`}>
      {tab === "overview" && <>
        <div className="turn-stats">{[["Active allocations", `${status.active_allocations} / ${status.max_allocations}`, "Across all transports"], ["Sent to peers", bytes(status.bytes_sent), "UDP payload bytes"], ["Received from peers", bytes(status.bytes_received), "UDP payload bytes"], ["Credentials issued", String(status.credentials_issued), "Since the last restart"]].map(([label, value, hint]) => <div className="turn-card" key={label}><div className="turn-small">{label}</div><div className="turn-value">{value}</div><div className="turn-small">{hint}</div></div>)}</div>
        {!status.tls && <div className="turn-banner"><div className="turn-row"><span>Set up a certificate to enable TURN over TLS on port {status.tls_port}.</span><button type="button" className="turn-button" onClick={() => setTab("settings")}>Configure TLS</button></div></div>}
        <div className="turn-grid"><section className="turn-card"><h2>Connection endpoints</h2>{[["UDP", `turn:${status.public_host}:${status.udp_port}?transport=udp`], ["TCP", `turn:${status.public_host}:${status.tcp_port}?transport=tcp`], ...(status.tls ? status.tls_ports.map(port => [`TLS ${port}`, `turns:${status.public_host}:${port}?transport=tcp`]) : [])].map(([label, value]) => <div className="turn-endpoint" key={label}><div className="turn-row"><span className="turn-small">TURN over {label}</span><button type="button" className="turn-button" onClick={() => void copy(value)} aria-label={`Copy ${label} endpoint`}>Copy</button></div><code>{value}</code></div>)}<p className="turn-small">Clients need temporary credentials as well as these endpoint URLs.</p></section>
          <section className="turn-card"><div className="turn-row"><h2>TLS certificate</h2><span className={`turn-badge ${status.tls ? "good" : "warn"}`}>{status.tls ? "Valid" : "Unavailable"}</span></div><dl className="turn-details"><dt>Hostname</dt><dd>{status.public_host}</dd><dt>Management</dt><dd>{status.managed_tls.automatic ? "Automatic · Let’s Encrypt" : "Imported certificate"}</dd><dt>Issuer</dt><dd>{status.tls_certificate.issuer || "Not configured"}</dd><dt>Expires</dt><dd>{status.tls_certificate.expires_at ? new Date(status.tls_certificate.expires_at * 1000).toLocaleDateString() : "—"}</dd><dt>Days remaining</dt><dd>{status.tls_certificate.days_remaining ?? "—"}</dd><dt>Fingerprint</dt><dd><code>{status.tls_certificate.fingerprint_sha256 || "—"}</code></dd></dl>{status.managed_tls.automatic && <><p role="status" className="turn-small">{status.managed_tls.phase}: {status.managed_tls.message || "Waiting for active deployment"}</p>{status.managed_tls.next_check ? <p className="turn-small">Next check {new Date(status.managed_tls.next_check * 1000).toLocaleString()}</p> : null}<button type="button" className="turn-button" disabled={!status.admitting || ["issuing", "dns"].includes(status.managed_tls.phase || "")} onClick={() => void request(endpoint(props.installId, props.projectId, "/tls/renew"), {}).then(() => setNotice("Certificate check queued. Failed requests retain their retry backoff.")).catch(error => setError(error.message))}>Check certificate</button></>}{!status.managed_tls.automatic && status.tls_certificate.days_remaining !== undefined && status.tls_certificate.days_remaining < 14 && <p className="turn-small">Renew the certificate before it expires to keep TLS connections available.</p>}</section>
          <section className="turn-card"><h2>Required network access</h2><table className="turn-table"><thead><tr><th>Port</th><th>Protocol</th><th>Purpose</th></tr></thead><tbody><tr><td>{status.udp_port}</td><td>UDP</td><td>TURN clients</td></tr><tr><td>{status.tcp_port}</td><td>TCP</td><td>TURN clients</td></tr>{status.tls_ports.map(port => <tr key={port}><td>{port}</td><td>TCP / TLS</td><td>Encrypted TURN clients</td></tr>)}<tr><td>{status.relay_port_min}–{status.relay_port_max}</td><td>UDP</td><td>Relay media</td></tr></tbody></table><p className="turn-small">Open these ports on the relay instance. HTTP proxies do not carry TURN traffic.</p></section>
          <section className="turn-card"><h2>Deployment and capacity</h2><dl className="turn-details"><dt>Public IPv4</dt><dd><code>{status.public_ip}</code></dd><dt>Admission</dt><dd>{status.admitting ? "Accepting new sessions" : "New sessions paused"}</dd><dt>Limit per session</dt><dd>{status.configuration.allocations_per_credential} allocations</dd><dt>Traffic limit</dt><dd>{bytes(Number(status.configuration.bytes_per_second))}/s per allocation</dd><dt>Dropped bytes</dt><dd>{bytes(status.bytes_dropped)}</dd></dl><p className="turn-small">Deploy this app independently on a dedicated public instance. Moving it requires draining active sessions first.</p></section>
        </div>
      </>}
      {tab === "settings" && <Settings props={props} status={status} notify={setNotice} />}
      {tab === "credentials" && <CredentialForm props={props} status={status} copy={copy} />}
    </div>}
    <footer className="turn-foot">TURN 0.3.0 · {updated ? `Updated ${new Date(updated).toLocaleTimeString()} · Refreshes every 5 seconds` : "Waiting for the relay"}</footer>
  </main></div></div>;
}
